def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    chairs = image_patch.find("chair")
    corners = [(0, 0), (image.width, 0), (0, image.height), (image.width, image.height)]

    corner_chairs = []
    for corner in corners:
        for chair in chairs:
            if is_in_front_of(chair, ImagePatch(image, *corner)):
                corner_chairs.append((corner, chair))

    if not corner_chairs:
        return image_patch

    _, closest_corner_chair = min(corner_chairs, key=lambda x: distance(x[1], ImagePatch(image, *x[0])))
    return closest_corner_chair

