    image_patch = ImagePatch(image)
    chairs = image_patch.find("chair")
    monitors = image_patch.find("monitor")

    if not chairs or not monitors:
        return image_patch

    monitor_depths = {mon: mon.compute_depth() for mon in monitors}
    behind_chairs = [ch for ch in chairs if all(is_behind(ch, mon) for mon in monitors)]

    if behind_chairs:
        return min(behind_chairs, key=lambda ch: monitor_depths[min(monitors, key=lambda m: distance(ch, m))])

    return chairs[0]

